def number(value, cx, baseline):
    s = str(value)
    x = cx - sum(DIGITS[c][0] for c in s) / 2
    out = []
    for c in s:
        advance, d = DIGITS[c]
        out.append('<path transform="translate(%.2f %s)" d="%s"/>' % (x, baseline, d))
        x += advance
    return "".join(out)


def main():
    prs, commits = (int(a) for a in sys.argv[1:3])
    if prs < 0 or commits < 0:
        raise SystemExit("counts must be non-negative")
    svg = (TEMPLATE.replace("@@PRS@@", number(prs, 370, 86))
           .replace("@@COMMITS@@", number(commits, 630, 86)))
    sys.stdout.buffer.write(svg.encode("utf-8"))


if __name__ == "__main__":
    main()
